const style=document.createElement('style');style.textContent=".quick-editor{width:min(460px,calc(100vw - 32px));max-height:calc(100dvh - 32px);overflow:auto;border:1px solid var(--line);background:var(--surface);color:var(--text);box-shadow:var(--shadow);}.quick-editor::backdrop{background:rgba(9,18,31,.5);}.quick-editor header{display:flex;align-items:center;justify-content:space-between;margin-bottom:22px;}.quick-editor header p{font-size:12px;color:var(--muted);margin:0 0 6px;}.quick-editor h2{font-size:21px;margin:0;}.quick-editor label{display:grid;gap:7px;font-size:13px;margin-top:14px;}.quick-editor input:not([type=checkbox]){width:100%;height:42px;padding:0 12px;border:1px solid var(--line);background:var(--bg);color:var(--text);font:inherit;}.quick-editor input:focus{outline:2px solid var(--accent-soft);border-color:var(--accent);}.quick-editor button{min-height:36px;padding:0 14px;border:1px solid var(--line);background:var(--surface);color:var(--text);cursor:pointer;}.quick-editor button.primary{background:#295d99;color:#fff;border:0;}.quick-editor footer{display:flex;justify-content:flex-end;gap:10px;margin-top:20px;}.quick-editor .quick-check{display:flex;align-items:center;}.quick-editor details{margin-top:18px;font-size:13px;color:var(--muted);}#quickMessage{font-size:13px;color:#d56767;min-height:18px;}.quick-editor button:disabled{opacity:.6;}@media(max-width:650px){.quick-editor{padding:22px;}.quick-editor input:not([type=checkbox]){font-size:16px;height:46px;}.quick-editor button{min-height:44px;}}.link-menu{position:fixed;z-index:20;min-width:140px;background:var(--surface);border:1px solid var(--line);box-shadow:var(--shadow);}.link-menu button{display:block;width:100%;text-align:left;border:0;background:transparent;color:var(--text);padding:10px 14px;font:inherit;font-size:13px;cursor:pointer;}.link-menu button:hover,.link-menu button:focus{background:var(--accent-soft);}.link-menu .danger{color:#c55252;}.sort-row{display:flex;align-items:center;gap:10px;padding:10px 0;border-bottom:1px solid var(--line);}.sort-row strong{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;font-size:13px;}.sort-number{font-size:12px;color:var(--muted);width:20px;}.sort-row button{padding:0 12px;}.sort-row button:disabled{opacity:.3;cursor:default;}@media(max-width:650px){.link-menu button{min-height:44px;}.sort-row button{min-width:44px;}}@media(max-width:650px){.app-shell #linkMenu{display:none!important;}}.quick-editor{border-radius:16px;padding:28px;}.quick-editor input:not([type=checkbox]){border-radius:9px;}.quick-editor button{border-radius:8px;}.quick-editor button.primary{background:#496bc0;}.link-menu{border-radius:12px;padding:6px;}.link-menu button{border-radius:7px;}.manager-dialog button{font:inherit;color:var(--text);border:1px solid var(--line);border-radius:7px;background:var(--surface);padding:8px 12px;cursor:pointer;}.manager-dialog{width:min(760px,calc(100vw - 40px));max-height:88vh;padding:26px;overflow:auto;}.manager-dialog header{display:flex;align-items:center;justify-content:space-between;}.manager-dialog h2{margin:4px 0 16px;font-size:22px;}.manager-dialog header p{font-size:12px;color:var(--muted);}.manager-tabs{display:flex;gap:8px;margin:4px 0 20px;}.manager-tabs .active{color:var(--accent);border-color:var(--accent);}#managerBody>label{display:grid;gap:8px;margin:14px 0;font-size:13px;}#managerBody select,#managerBody textarea,#managerBody input[type=file]{width:100%;box-sizing:border-box;padding:10px;border:1px solid var(--line);border-radius:7px;color:var(--text);background:var(--surface);font:inherit;}#managerBody .quick-check{display:flex;align-items:center;}.manager-hint,#managerMessage{color:var(--muted);font-size:13px;line-height:1.7;}#managerMessage{margin:16px 0 0;min-height:22px;}.import-list{max-height:40vh;overflow:auto;margin:14px 0;}.import-row,.restore-row{display:flex;align-items:center;gap:12px;border-bottom:1px solid var(--line);padding:12px 2px;font-size:13px;}.import-row>span,.restore-row>span{min-width:0;flex:1;}.import-row small,.restore-row small{display:block;color:var(--muted);margin-top:5px;overflow-wrap:anywhere;}.import-row input{flex:none;}.restore-row button{flex:none;}.check-actions{display:flex;gap:8px;}.import-row small[data-state=ok]{color:#43866d;}.import-row small[data-state=suspect]{color:#c36c40;}.manager-dialog button:disabled{opacity:.45;cursor:default;}.manager-tabs{flex-wrap:wrap;}#quickLatest{white-space:pre-wrap;overflow-wrap:anywhere;font-family:inherit;font-size:12px;line-height:1.7;padding:10px;background:var(--accent-soft);border-radius:8px}.session-dialog{max-width:420px}.session-dialog p{font-size:13px;line-height:1.6}";document.head.append(style);